 class DebugPrintRule(configRules: List<RulesConfig>) : DiktatRule(
     NAME_ID,
     configRules,
     listOf(Warnings.DEBUG_PRINT)
 ) {
     override fun logic(node: ASTNode) {
         checkPrintln(node)
         checkJsConsole(node)
